import { test } from "node:test";
import assert from "node:assert/strict";
import fixture from "./fixtures/vista-loading.json" with { type: "json" };
import { introKeyframes, loadingRingAnimation, loadingRingPose, vistaMotion } from "../lib/vista-motion.ts";

test("six ring layers keep a fixed diameter while matching original rotation through one minute", () => {
  // Independent expected positions/UVs copied from the existing original executable oracle,
  // not generated by the website formula. Browser trig has a bounded float tolerance.
  const near = (actual: number, expected: number, where: string) => {
    assert.ok(Math.abs(actual - expected) < 0.00001, `${where}: ${actual} vs ${expected}`);
  };
  assert.equal(fixture.cases.length, 20);
  const initial = fixture.cases.find((sample) => sample.ms === 0)!;
  const corners = [[-0.5, -0.5], [-0.5, 0.5], [0.5, 0.5], [0.5, -0.5]];
  for (const sample of fixture.cases) {
    sample.rings.forEach((vertices, layer) => {
      const pose = loadingRingPose(sample.ms / 1000, Math.floor(layer / 2) + 1, layer % 2 === 1);
      vertices.forEach(([, , u, v], corner) => {
        const [dx, dy] = corners[corner];
        const [x, y] = initial.rings[layer][corner];
        const context = `${sample.ms}ms layer ${layer} vertex ${corner}`;
        near(0.5 + dx * pose.size * 480 / 640, x, `${context} X`);
        near(0.5 + dy * pose.size, y, `${context} Y`);
        const [a, b, c, d] = pose.matrix.map((n) => n / pose.size);
        near(0.5 + a * dx + c * dy, u, `${context} U`);
        near(0.5 + b * dx + d * dy, v, `${context} V`);
      });
    });
  }
});

test("browser animation preserves startup, rotation direction, diameter and full turns against the original oracle", () => {
  for (const sample of fixture.cases) {
    sample.rings.forEach((vertices, layer) => {
      const motion = loadingRingAnimation(Math.floor(layer / 2) + 1, layer % 2 === 1);
      const startAngle = parseFloat(motion.spin.keyframes[0].rotate);
      const fullTurn = parseFloat(motion.spin.keyframes[1].rotate) - startAngle;
      const angle = sample.ms < motion.startup.duration
        ? startAngle * (sample.ms / motion.startup.duration) ** 2
        : startAngle + fullTurn * (sample.ms - motion.spin.delay) / motion.spin.duration;
      const size = Number(motion.transform.match(/matrix\(0,([^,]+)/)![1]);
      const corners = [[-0.5, -0.5], [-0.5, 0.5], [0.5, 0.5], [0.5, -0.5]];
      assert.ok(Math.abs(Math.abs(fullTurn) - 2 * Math.PI) < 1e-12);
      assert.equal(Math.sign(fullTurn), layer % 2 ? -1 : 1);
      assert.equal(size, Math.fround(0.936 / (Math.floor(layer / 2) + 1)));
      vertices.forEach(([, , u, v], corner) => {
        const [x, y] = corners[corner];
        const actualU = 0.5 - Math.sin(angle) * x + Math.cos(angle) * y;
        const actualV = 0.5 + Math.cos(angle) * x + Math.sin(angle) * y;
        assert.ok(Math.abs(actualU - u) < 0.00001, `${sample.ms}ms layer ${layer} U`);
        assert.ok(Math.abs(actualV - v) < 0.00001, `${sample.ms}ms layer ${layer} V`);
      });
    });
  }
});

test("menu tracks preserve their one-based IDs, original linear keys, focus timings and U velocities", () => {
  assert.equal(vistaMotion.source.cache_sha256, "eb259c207da26adc1820ae0757d23efb4ce1d2c2018956635d1094c8364f6b44");
  assert.deepEqual([vistaMotion.intro.panel.id, vistaMotion.intro.panel.ms], [3, 310]);
  assert.deepEqual([vistaMotion.intro.player.id, vistaMotion.intro.player.ms], [11, 230]);
  assert.deepEqual([vistaMotion.intro.wordmark.id, vistaMotion.intro.wordmark.ms], [30, 250]);
  assert.deepEqual(introKeyframes("frame", 640).map((k) => k.opacity), [0, 0, 0, 1]);
  assert.equal(introKeyframes("panel", 640)[0].transform, "translate(1024px,0px)");
  assert.equal(introKeyframes("panel", 320)[0].transform, "translate(512px,0px)");
  assert.deepEqual(vistaMotion.menu.focus.slice(0, 3).map((t) => t.ms), [120, 200, 1]);
  assert.deepEqual(vistaMotion.player.focus.slice(0, 3).map((t) => t.ms), [1, 300, 1]);
  assert.deepEqual(vistaMotion.menu.bitmaps.map((b) => Math.fround(b.scroll[0])), [0, 0, Math.fround(0.2), Math.fround(-0.2)]);
  assert.ok(vistaMotion.player.bitmaps.every((b) => b.fps === 0 && b.scroll.every((n) => n === 0)));
});
